static inline float gelu_f(float x)
{
    /* outside +-8 the function is exactly 0 or x to float precision */
    if (x <= -GELU_R) return 0.0f;
    if (x >=  GELU_R) return x;
    float t = (x + GELU_R) * GELU_SCALE;
    int   i = (int)t;
    float f = t - (float)i;
    return gelu_lut[i] + f * (gelu_lut[i + 1] - gelu_lut[i]);
}

/* dense: y[o] = W[o][.] . x[.] + b[o]
 * Blocked over OUTPUTS, 4 rows at a time: x[] is identical for every
 * output neuron, so loading it once per 4 rows cuts SRAM traffic 4x.
 * Per 4 MACs: 4 weight loads + 1 activation load + 4 vfma. */
#define ACT_LINEAR    0
#define ACT_GELU      1
#define ACT_RELU      2
#define ACT_SIGMOID   3
#define ACT_TANH      4
#define ACT_SOFTPLUS  5
#define ACT_ELU       6

/* --- SMLAD: one instruction, two int16 multiply-accumulates ---
 * SMLAD Rd, Rn, Rm, Ra:  Rd = Ra + Rn[15:0]*Rm[15:0] + Rn[31:16]*Rm[31:16]
 * That is the whole reason int16 wins on this core: the M4 is single-issue
 * and in-order, so what costs is INSTRUCTIONS, not bytes. fp32 needs one
 * VFMA per MAC; SMLAD does two MACs per instruction. */
#if defined(__ARM_FEATURE_DSP) && __ARM_FEATURE_DSP
static inline int32_t smlad_(uint32_t a, uint32_t b, int32_t acc)
{
    __asm("smlad %0, %1, %2, %0" : "+r"(acc) : "r"(a), "r"(b));
    return acc;
}
#else
/* portable fallback so the golden self-test can build and run on a host */
static inline int32_t smlad_(uint32_t a, uint32_t b, int32_t acc)
{
    int32_t a0 = (int16_t)(a & 0xFFFFu), a1 = (int16_t)(a >> 16);
    int32_t b0 = (int16_t)(b & 0xFFFFu), b1 = (int16_t)(b >> 16);
    return acc + a0 * b0 + a1 * b1;
}
#endif

/* float vector -> packed int16 pairs. One VCVTR per element on the M4. */
static void quantize(const float *x, uint32_t *xq, int n, float inv_s)
{
    for (int i = 0; i < n; i += 2) {
        int32_t a = (int32_t)(x[i    ] * inv_s + (x[i    ] < 0.0f ? -0.5f : 0.5f));
        int32_t b = (int32_t)(x[i + 1] * inv_s + (x[i + 1] < 0.0f ? -0.5f : 0.5f));
        if (a >  QMAX) a =  QMAX; else if (a < -QMAX) a = -QMAX;
        if (b >  QMAX) b =  QMAX; else if (b < -QMAX) b = -QMAX;
        xq[i >> 1] = ((uint32_t)b << 16) | ((uint32_t)a & 0xFFFFu);
    }
}

static inline float activate(float v, int act)
{
    switch (act) {
        case ACT_GELU:     v = gelu_f(v); break;
        case ACT_SIGMOID:  v = 1.0f / (1.0f + expf(-v)); break;
    default: break;   /* ACT_LINEAR */
    }
    return v;
}

static void dense(const uint32_t *W, const float *dq, const float *bias,
                  const uint32_t *xq, float *y, int n_in, int n_out, int act)
{
    const int nh = n_in >> 1;              /* packed words per row */
    const int o4 = n_out & ~3;
    int o = 0;
    /* blocked over OUTPUTS: xq[] is loaded once and reused by 4 rows, and
     * the 4 accumulators are independent so the MAC latency is hidden */
    for (; o < o4; o += 4) {
        const uint32_t *r0 = W + (size_t)o * nh;
        const uint32_t *r1 = r0 + nh;
        const uint32_t *r2 = r1 + nh;
        const uint32_t *r3 = r2 + nh;
        int32_t a0 = 0, a1 = 0, a2 = 0, a3 = 0;
        for (int i = 0; i < nh; ++i) {
            const uint32_t xi = xq[i];
            a0 = smlad_(r0[i], xi, a0);
            a1 = smlad_(r1[i], xi, a1);
            a2 = smlad_(r2[i], xi, a2);
            a3 = smlad_(r3[i], xi, a3);
        }
        y[o    ] = activate((float)a0 * dq[o    ] + bias[o    ], act);
        y[o + 1] = activate((float)a1 * dq[o + 1] + bias[o + 1], act);
        y[o + 2] = activate((float)a2 * dq[o + 2] + bias[o + 2], act);
        y[o + 3] = activate((float)a3 * dq[o + 3] + bias[o + 3], act);
    }
    for (; o < n_out; ++o) {              /* tail: heads are 1 or 3 wide */
        const uint32_t *row = W + (size_t)o * nh;
        int32_t a = 0;
        for (int i = 0; i < nh; ++i) a = smlad_(row[i], xq[i], a);
        y[o] = activate((float)a * dq[o] + bias[o], act);
    }
}

/* TactileFCNDecoder._decode:
 *   ax,ay,az = |ux|/a, |uy|/b, |uz|/c
 *   F = (ax**(2/eps2) + ay**(2/eps2))**(eps2/eps1) + az**(2/eps1)
 *   k = F**(-eps1/2);   u = k * u                                     */
static void normalize_u(float *u)
{
    float ax = fabsf(u[0]) / NN_SE_A;
    float ay = fabsf(u[1]) / NN_SE_B;
    float az = fabsf(u[2]) / NN_SE_C;
    /* eps1=1, eps2=0.5 exactly: 2/eps2=4, eps2/eps1=1/2, 2/eps1=2
     *   F = sqrt(ax^4 + ay^4) + az^2,   k = 1/sqrt(F).  No powf.  */
    float x2 = ax * ax, y2 = ay * ay;
    float F = sqrtf(x2 * x2 + y2 * y2) + az * az;
    float k = 1.0f / sqrtf(F);
    /* No F=0 guard, matching TactileFCNDecoder._decode. F is zero only if
     * the direction head emits exactly (0,0,0). Built with -Ofast, which
     * implies -ffinite-math-only, the compiler would delete such a guard
     * anyway. */
    u[0] *= k; u[1] *= k; u[2] *= k;
}

#define NN_SCRATCH 64
static float buf_a[NN_SCRATCH], buf_b[NN_SCRATCH], buf_z[NN_SCRATCH];
static uint32_t buf_q[128];   /* packed int16 activations */

/* TactileRegressor.forward = decoder(encoder(x)) */
void nn_forward_raw(const float *in, nn_output_t *out)
{
    /* encoder:  256->64->64 */
    quantize(in, buf_q, 256, ISX_ENCODER_0);
    dense(w_encoder_0, d_encoder_0, b_encoder_0, buf_q, buf_a, 256, 64, ACT_GELU);
    quantize(buf_a, buf_q, 64, ISX_ENCODER_1);
    dense(w_encoder_1, d_encoder_1, b_encoder_1, buf_q, buf_b, 64, 64, ACT_GELU);

    /* trunk:  64->64->64 */
    quantize(buf_b, buf_q, 64, ISX_TRUNK_0);
    dense(w_trunk_0, d_trunk_0, b_trunk_0, buf_q, buf_a, 64, 64, ACT_GELU);
    quantize(buf_a, buf_q, 64, ISX_TRUNK_1);
    dense(w_trunk_1, d_trunk_1, b_trunk_1, buf_q, buf_z, 64, 64, ACT_LINEAR);

    /* flag:  64->64->1 */
    quantize(buf_z, buf_q, 64, ISX_FLAG_0);
    dense(w_flag_0, d_flag_0, b_flag_0, buf_q, buf_a, 64, 64, ACT_GELU);
    quantize(buf_a, buf_q, 64, ISX_FLAG_1);
    dense(w_flag_1, d_flag_1, b_flag_1, buf_q, buf_b, 64, 1, ACT_SIGMOID);

    out->contact_prob = buf_b[0];   /* sigmoid applied inside the layer */

    /* force:  64->64->3 */
    quantize(buf_z, buf_q, 64, ISX_FORCE_0);
    dense(w_force_0, d_force_0, b_force_0, buf_q, buf_a, 64, 64, ACT_GELU);
    quantize(buf_a, buf_q, 64, ISX_FORCE_1);
    dense(w_force_1, d_force_1, b_force_1, buf_q, out->F, 64, 3, ACT_LINEAR);

    /* dir:  64->64->3 */
    quantize(buf_z, buf_q, 64, ISX_DIR_0);
    dense(w_dir_0, d_dir_0, b_dir_0, buf_q, buf_a, 64, 64, ACT_GELU);
    quantize(buf_a, buf_q, 64, ISX_DIR_1);
    dense(w_dir_1, d_dir_1, b_dir_1, buf_q, out->u, 64, 3, ACT_LINEAR);

    normalize_u(out->u);
}

/* --- history ring buffer --- */
static float ring[NN_HISTORY][NN_N_TAXEL];
static int   head = 0, fill = 0;

void nn_reset(void) { memset(ring, 0, sizeof ring); head = 0; fill = 0; }

void nn_push(const float *taxels)
{
    memcpy(ring[head], taxels, NN_N_TAXEL * sizeof(float));
    head = (head + 1) % NN_HISTORY;
    if (fill < NN_HISTORY) ++fill;
}

int nn_infer(nn_output_t *out)
{
    static float in[NN_IN_CHAN];
    const float inv = 1.0f / NN_X_MAX;
    if (fill < NN_HISTORY) return 0;
    for (int t = 0; t < NN_HISTORY; ++t) {
        const float *s = ring[(head + t) % NN_HISTORY];  /* t = 0 -> oldest */
        float *d = &in[t * NN_N_TAXEL];                  /* TIME-MAJOR      */
        for (int c = 0; c < NN_N_TAXEL; ++c) d[c] = s[c] * inv;
    }
    nn_forward_raw(in, out);
    return 1;
}
